const input = $json.body ?? $json.payload ?? $json.data ?? $json;
const rawFields = input.fields ?? input.data ?? input;
const fields = Array.isArray(rawFields)
  ? Object.fromEntries(rawFields.map((field) => [String(field.name ?? field.key ?? '').toLowerCase(), field.value]))
  : Object.fromEntries(Object.entries(rawFields).map(([key, value]) => [key.toLowerCase(), value]));

const first = (...keys) => {
  for (const key of keys) {
    const value = fields[key.toLowerCase()];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
  }
  return '';
};

const fullName = first('name', 'full name', 'fullname');
const nameParts = fullName.split(/\s+/).filter(Boolean);
const firstname = first('firstname', 'first name', 'first_name') || nameParts[0] || '';
const lastname = first('lastname', 'last name', 'last_name') || nameParts.slice(1).join(' ') || 'Webflow Lead';
const email = first('email', 'email address', 'e-mail').toLowerCase();
const phone = first('phone', 'phone number', 'tel', 'telephone').replace(/[^\d+(). -]/g, '');
const company = first('company', 'company name', 'organization') || 'Individual';
const message = first('message', 'notes', 'details', 'project details');
const source = first('source', 'lead source') || 'Web';
const honeypot = first('website', 'url', 'honeypot', 'company website');
const disposableDomains = new Set(['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com']);
const emailDomain = email.includes('@') ? email.split('@').pop() : '';
const reasons = [];

if (!email) reasons.push('email_missing');
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) reasons.push('email_invalid');
if (honeypot) reasons.push('honeypot_filled');
if (disposableDomains.has(emailDomain)) reasons.push('disposable_email');

let lead_quality_status = 'accepted';
if (reasons.includes('email_missing') || reasons.includes('email_invalid')) lead_quality_status = 'rejected';
else if (reasons.length) lead_quality_status = 'quarantined';

return [{
  json: {
    submission_id: String(input.id ?? input._id ?? $execution.id),
    firstname,
    lastname,
    email,
    phone,
    company,
    message,
    source,
    lead_quality_status,
    lead_quality_reasons: reasons
  }
}];

const lead = $('Normalize and qualify Webflow lead').first().json;
const crmRecordId = $json.id || $json.Id || null;

// SETUP: choose 'sdr', 'cs', or 'sales', then replace the example inboxes.
const NOTIFICATION_TEAM = 'sales';
const TEAM_INBOXES = {
  sdr: 'user@example.com',
  cs: 'user@example.com',
  sales: 'user@example.com'
};

const freeDomains = new Set(['gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'yahoo.com', 'icloud.com', 'proton.me', 'protonmail.com']);
const disposableDomains = new Set(['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'yopmail.com']);
const emailDomain = lead.email.includes('@') ? lead.email.split('@').pop() : '';
let leadScore = 0;
const scoreReasons = [];

if (emailDomain && !freeDomains.has(emailDomain) && !disposableDomains.has(emailDomain)) { leadScore += 40; scoreReasons.push('business_email'); }
if (lead.company && lead.company !== 'Individual') { leadScore += 25; scoreReasons.push('company_provided'); }
if (lead.phone) { leadScore += 15; scoreReasons.push('phone_provided'); }
if ((lead.message || '').length >= 40) { leadScore += 20; scoreReasons.push('detailed_message'); }

const notificationTeam = Object.prototype.hasOwnProperty.call(TEAM_INBOXES, NOTIFICATION_TEAM) ? NOTIFICATION_TEAM : 'sales';
return [{ json: {
  ...lead,
  crm_record_id: crmRecordId,
  lead_score: leadScore,
  lead_score_reasons: scoreReasons,
  high_quality: leadScore >= 70,
  notification_team: notificationTeam,
  notification_email: TEAM_INBOXES[notificationTeam]
} }];
